     1→/**
     2→ * Archivo principal del listado de empresas
     3→ * @author Andres Morales
     4→ */
     5→
     6→var empresas_datos_ids = [];
     7→var empresas_seleccionadas = [];
     8→var nombre_tabla_empresas = 'tabla-empresas';
     9→var json_filtros = {};
    10→var filtro_html = '';
    11→var paises = [];
    12→var empresa_id_eliminar = null;
    13→var tabla_empresas = null;
    14→let creditos_empresa_id = null;
    15→let creditos_totales_empresa = 0;
    16→let creditos_consumidos_empresa = 0;
    17→
    18→const CONFIGURACION_TABLAS = {
    19→    autoWidth: true,
    20→    responsive: false,
    21→    processing: false,
    22→    serverSide: false,
    23→    searching: true,
    24→    deferRender: true,
    25→    paging: true,
    26→    aaSorting: [],
    27→    language: lenguaje_componente_datatables,
    28→    lengthMenu: [[10, 25, 50, 100, 200], [10, 25, 50, 100, 200]],
    29→    pageLength: 10,
    30→    scrollY: 'calc(100vh - 500px)',
    31→    scrollCollapse: true,
    32→    scrollX: true,
    33→};
    34→
    35→tabla_empresas = $('#tabla-empresas').DataTable({
    36→    ...CONFIGURACION_TABLAS,
    37→    ajax: {
    38→        url: '/empresas-listado-tabla',
    39→        data: function(datos) {
    40→            datos.solo_principales = true;
    41→            datos.activo = archivadas ? false : true;
    42→            datos.ordenar_sentido = $('#filtro_mas_recientes').val();
    43→            datos.ordenar_por = 'created_at';
    44→
    45→            if (json_filtros.estado_plan_filtro) datos.estado_plan_id = json_filtros.estado_plan_filtro;
    46→            if (json_filtros.tipo_prueba_filtro) datos.tipo_prueba_id = json_filtros.tipo_prueba_filtro;
    47→            if (json_filtros.plan_filtro) datos.plan_id = json_filtros.plan_filtro;
    48→            if (json_filtros.ejecutivo_filtro) datos.ejecutivo_id = json_filtros.ejecutivo_filtro;
    49→            if (json_filtros.pais_filtro) datos.pais_id = json_filtros.pais_filtro;
    50→            if (json_filtros.departamento_filtro) datos.departamento_id = json_filtros.departamento_filtro;
    51→            if (json_filtros.ciudad_filtro) datos.ciudad_id = json_filtros.ciudad_filtro;
    52→
    53→            if (typeof json_filtros.fecha_creacion_filtro === 'string') {
    54→                let partes_fecha = json_filtros.fecha_creacion_filtro.split(' a ');
    55→                if (partes_fecha[0]) datos.fecha_creacion_desde = partes_fecha[0];
    56→                if (partes_fecha[1]) datos.fecha_creacion_hasta = partes_fecha[1];
    57→            }
    58→        },
    59→        dataSrc: function(json) {
    60→            let filas = [];
    61→            json.forEach(empresa => {
    62→                filas.push({ ...empresa, tipo: 'empresa' });
    63→                if (empresa.sucursales && empresa.sucursales.length > 0) {
    64→                    empresa.sucursales.forEach(sucursal => {
    65→                        filas.push({
    66→                            ...sucursal,
    67→                            tipo: 'sucursal',
    68→                            empresa_id_padre: empresa.id,
    69→                            plan_seleccion_padre: empresa.plan_procesos_de_seleccion,
    70→                            plan_organizacional_padre: empresa.plan_procesos_organizacionales,
    71→                            plan_vocacional_padre: empresa.plan_procesos_vocacionales
    72→                        });
    73→                    });
    74→                }
    75→            });
    76→            return filas;
    77→        }
    78→    },
    79→    columns: [
    80→        {
    81→            data: null,
    82→            title: `<div class="check-container my-1 me-1">
    83→                <input type="checkbox" id="check-seleccionar-todos-empresas" onchange="seleccionarTodasEmpresas(this.checked);"/>
    84→            </div>`,
    85→            orderable: false,
    86→            className: 'text-center',
    87→            render: (dato) => {
    88→                let checked = empresas_seleccionadas.some(item => item.id == dato.id) ? 'checked' : '';
    89→                return `<div class="check-container my-1 me-1">
    90→                    <input type="checkbox" class="form-check-input" value="${dato.id}" onchange="seleccionarCheckboxEmpresa(this.checked, this.value);" ${checked}/>
    91→                </div>`;
    92→            }
    93→        },
    94→        {
    95→            data: null,
    96→            title: 'Suc.',
    97→            orderable: false,
    98→            className: 'text-start',
    99→            render: (dato) => {
   100→                if (dato.tipo === 'empresa' && dato.sucursales && dato.sucursales.length > 0) {
   101→                    return `<div class="width-60px rounded-1 badge-estado-plan badge-estado-inactivo nowrap pointer" onclick="mostrarOcultarSucursales(this, ${dato.id})">
   102→                        ${dato.sucursales_count} <i class="bi bi-caret-down-fill"></i>
   103→                    </div>`;
   104→                }
   105→                return '';
   106→            }
   107→        },
   108→        {
   109→            data: null,
   110→            title: 'ID',
   111→            className: 'text-center',
   112→            render: (dato) => dato.id || '-'
   113→        },
   114→        {
   115→            data: null,
   116→            title: 'Empresa',
   117→            render: (dato) => dato.nombre_comercial || '-'
   118→        },
   119→        {
   120→            data: null,
   121→            title: 'Razon social',
   122→            render: (dato) => dato.razon_social || '-'
   123→        },
   124→        {
   125→            data: null,
   126→            title: 'NIT',
   127→            render: (dato) => dato.documento || '-'
   128→        },
   129→        {
   130→            data: null,
   131→            title: 'Ejecutivo',
   132→            render: (dato) => dato.ejecutivo?.nombre_completo || '-'
   133→        },
   134→        {
   135→            data: null,
   136→            title: `
   137→                <i class="bi bi-person-fill fs-5" onmouseover="mostrarTooltip(this)" onmouseout="ocultarTooltip(this)">
   138→                    <span class="tooltip-bottom tooltip-icon-bottom">Selección</span>
   139→                </i>
   140→            `,
   141→            className: 'px-3 text-center position-relative overflow-visible',
   142→            render: (dato) => {
   143→                let plan = dato.tipo === 'sucursal'
   144→                    ? dato.plan_seleccion_padre
   145→                    : dato.plan_procesos_de_seleccion;
   146→                return obtenerEstadoPlan(
   147→                    plan?.estado?.id,
   148→                    plan?.estado?.nombre,
   149→                    plan?.por_facturar,
   150→                    plan?.renovando,
   151→                    plan?.id,
   152→                    plan?.plan_proximo
   153→                );
   154→            }
   155→        },
   156→        {
   157→            data: null,
   158→            title: `
   159→                <img src="/iconos/icono_ia.svg" class="fs-5" onmouseover="mostrarTooltip(this)" onmouseout="ocultarTooltip(this)">
   160→            `,
   161→            className: 'px-3 text-center position-relative overflow-visible',
   162→            render: (dato) => {
   163→                let plan = dato?.plan_creditos || null;
   164→                return obtenerEstadoPlanCreditos(
   165→                    plan?.estado?.id,
   166→                    plan?.estado?.nombre,
   167→                    plan?.por_facturar,
   168→                    plan?.renovando,
   169→                    plan?.id,
   170→                    plan?.plan_proximo,
   171→                    plan?.empresa_id,
   172→                    plan?.plan_credito?.nombre,
   173→                    plan?.plan_credito?.creditos,
   174→                    plan?.creditos_plan,
   175→                    plan?.creditos_disponibles
   176→                );
   177→            }
   178→        },
   179→        {
   180→            data: null,
   181→            title: 'Ubicación',
   182→            visible: false,
   183→            render: (d) => d.ciudad?.nombre || '-'
   184→        },
   185→        {
   186→            data: null,
   187→            title: 'Número de celular',
   188→            visible: false,
   189→            render: (dato) => dato.celular || '-'
   190→        },
   191→        {
   192→            data: null,
   193→            title: 'Correo de facturación',
   194→            visible: false,
   195→            render: (dato) => dato.email_facturacion || '-'
   196→        },
   197→        {
   198→            data: null,
   199→            title: 'Fecha de creación',
   200→            visible: false,
   201→            render: (dato) => dato.created_at || '-'
   202→        },
   203→        {
   204→            data: null,
   205→            title: 'Progreso de creación',
   206→            visible: false,
   207→            render: (dato) => dato.porcentaje_creacion || '-'
   208→        },
   209→        {
   210→            data: null,
   211→            title: 'Tamaño de empresa',
   212→            visible: false,
   213→            render: (d) => d.tamano_empresa?.nombre || '-'
   214→        },
   215→        {
   216→            data: null,
   217→            title: 'Sector',
   218→            visible: false,
   219→            render: (d) => d.sector?.nombre || '-'
   220→        },
   221→        {
   222→            data: null,
   223→            title: 'Dirección',
   224→            visible: false,
   225→            render: (dato) => dato.direccion || '-'
   226→        },
   227→        {
   228→            data: null,
   229→            title: 'Representante legal',
   230→            visible: false,
   231→            render: (dato) => dato.nombre_representante || '-'
   232→        },
   233→        {
   234→            data: null,
   235→            title: 'Acciones',
   236→            orderable: false,
   237→            className: 'px-3 text-center',
   238→            render: (dato) => {
   239→                let texto_archivar = archivadas ? 'Desarchivar' : 'Archivar';
   240→                return `
   241→                    <div class="dropdown">
   242→                        <i class="bi bi-three-dots dropdown-toggle text-blue-40 pointer" data-bs-toggle="dropdown" data-bs-auto-close="outside"></i>
   243→                        <div class="dropdown-menu">
   244→                            <a href="/empresas-gestionar/${dato.id}" class="dropdown-item no-visited pointer py-2">Gestionar empresa</a>
   245→                            <div class="dropdown-item no-visited pointer py-2" onclick="abrirHistorialCambios(${dato.id}, '${dato.razon_social}', '${dato.creado_administrador}')">Historial de cambios</div>
   246→                            <div class="dropdown-item no-visited pointer py-2" onclick="modalArchivarEmpresa(${dato.id})">${texto_archivar}</div>
   247→                            <div class="dropdown-item no-visited pointer py-2" onclick="abrirDetalleArchivado(${dato.id}, '${dato.razon_social}', '${dato.comentario}')">Detalle de archivado</div>
   248→                            <div class="dropdown-item no-visited pointer py-2" onclick="cambiarEmpresa(${dato.id},)">Cambiar a esta empresa</div>
   249→                            <div class="dropdown-item no-visited pointer py-2 text-danger" onclick="modalEliminarEmpresa(${dato.id}, '${dato.razon_social}')">Eliminar</div>
   250→                        </div>
   251→                    </div>
   252→                `;
   253→            }
   254→        }
   255→    ],
   256→    createdRow: function(row, dato) {
   257→        if (dato.tipo === 'sucursal') {
   258→            $(row).addClass(`empresa-${dato.empresa_id_padre} d-none bg-gray-90`);
   259→            $(row).find('td').addClass('bg-gray-90');
   260→        }
   261→    },
   262→    drawCallback: function() {
   263→        empresas_datos_ids = $('#tabla-empresas').DataTable().data().toArray();
   264→
   265→        // Aplicar estilos de fondo gris a las sucursales en todas las columnas visibles
   266→        $('#tabla-empresas tbody tr').each(function() {
   267→            if ($(this).hasClass('bg-gray-90')) {
   268→                $(this).find('td').addClass('bg-gray-90');
   269→            }
   270→        });
   271→
   272→        inicializarTooltips();
   273→        sincronizarEncabezadoTabla();
   274→        validarSeleccionados();
   275→    },
   276→    initComplete: function() {
   277→        empresas_datos_ids = $('#tabla-empresas').DataTable().data().toArray();
   278→        inicializarTooltips();
   279→        cargarDataTablas();
   280→        $('#tabla-empresas').parent().css('height', 'calc(100vh - 500px)');
   281→
   282→        setTimeout(() => {
   283→            if (tabla_empresas) {
   284→                tabla_empresas.columns.adjust().draw(false);
   285→                sincronizarEncabezadoTabla();
   286→            }
   287→        }, 100);
   288→    }
   289→});
   290→
   291→$(document).ready(function() {
   292→    $(document).on('change', '#filtro_mas_recientes', function() {
   293→        actualizarDatatables(nombre_tabla_empresas);
   294→    });
   295→
   296→    $.getJSON('/paises-listado-completo', function(data) {
   297→        paises = data.data || [];
   298→        $('#pais_filtro').empty().append('<option value="">Todos</option>');
   299→        paises.forEach(pais => {
   300→            $('#pais_filtro').append(`<option value="${pais.id}">${pais.nombre}</option>`);
   301→        });
   302→    });
   303→});
   304→
   305→/**
   306→ * Función OBLIGATORIA para aplicar filtros dropdown.
   307→ *
   308→ * @param {string} filtro id del elemento html del filtro
   309→ * @param {Object} filtros filtros aplicados
   310→ * @returns {void}
   311→ * @author Andres Morales
   312→ * @author José Manuel Jiménez
   313→ */
   314→function aplicarFiltrosDropdown(filtro, filtros) {
   315→    filtro_html = filtro;
   316→    json_filtros = filtros;
   317→    if ($('#modal-detalle-consumo-creditos').hasClass('show')) {
   318→        actualizarDatatables('tabla-consumo-creditos');
   319→    } else {
   320→        actualizarDatatables(nombre_tabla_empresas);
   321→    }
   322→}
   323→
   324→/**
   325→ * Función OPCIONAL para restablecer filtros dependientes.
   326→ *
   327→ * @returns {void}
   328→ * @author Andres Morales
   329→ */
   330→function restablecerFiltrosDropdownAdicional() {
   331→    $('#plan_filtro').empty().append('<option value="">Todos</option>');
   332→    $('#departamento_filtro').empty().append('<option value="">Todos</option>');
   333→    $('#ciudad_filtro').empty().append('<option value="">Todos</option>');
   334→}
   335→
   336→/**
   337→ * Cargar planes según tipo de prueba seleccionado.
   338→ *
   339→ * @param {number} tipo_prueba_id ID del tipo de prueba
   340→ * @returns {void}
   341→ * @author José Manuel Jiménez
   342→ * @author Andres Morales
   343→ */
   344→function cargarPlanesFiltro(tipo_prueba_id) {
   345→    $('#plan_filtro').empty().append('<option value="">Todos</option>');
   346→
   347→    if (!tipo_prueba_id) return;
   348→
   349→    $.ajax({
   350→        type: 'GET',
   351→        url: '/planes-listado',
   352→        data: { tipo_prueba_id: tipo_prueba_id }
   353→    }).done((respuesta) => {
   354→        respuesta.data.forEach(plan => {
   355→            $('#plan_filtro').append(`<option value="${plan.id}">${plan.nombre}</option>`);
   356→        });
   357→        $('#plan_filtro').trigger('change');
   358→    });
   359→}
   360→
   361→/**
   362→ * Cargar departamentos según país seleccionado.
   363→ *
   364→ * @param {number} pais_id ID del país
   365→ * @returns {void}
   366→ * @author José Manuel Jiménez
   367→ * @author Andres Morales
   368→ */
   369→function cargarDepartamentosFiltro(pais_id) {
   370→    $('#departamento_filtro').empty().append('<option value="">Todos</option>');
   371→    $('#ciudad_filtro').empty().append('<option value="">Todos</option>');
   372→
   373→    if (!pais_id) return;
   374→
   375→    const PAIS = paises.find(p => p.id == pais_id);
   376→    if (PAIS?.departamentos) {
   377→        PAIS.departamentos.forEach(dep => {
   378→            $('#departamento_filtro').append(`<option value="${dep.id}">${dep.nombre}</option>`);
   379→        });
   380→    }
   381→}
   382→
   383→/**
   384→ * Cargar ciudades según departamento seleccionado.
   385→ *
   386→ * @param {number} departamento_id ID del departamento
   387→ * @returns {void}
   388→ * @author José Manuel Jiménez
   389→ * @author Andres Morales
   390→ */
   391→function cargarCiudadesFiltro(departamento_id) {
   392→    $('#ciudad_filtro').empty().append('<option value="">Todos</option>');
   393→
   394→    if (!departamento_id) return;
   395→
   396→    paises.forEach(pais => {
   397→        const DEP = pais.departamentos?.find(d => d.id == departamento_id);
   398→        if (DEP?.ciudades) {
   399→            DEP.ciudades.forEach(ciudad => {
   400→                $('#ciudad_filtro').append(`<option value="${ciudad.id}">${ciudad.nombre}</option>`);
   401→            });
   402→        }
   403→    });
   404→}
   405→
   406→/**
   407→ * Mostrar/ocultar sucursales de una empresa.
   408→ *
   409→ * @param {HTMLElement} elemento Botón clickeado
   410→ * @param {number} empresa_id_padre ID de la empresa padre
   411→ * @returns {void}
   412→ * @author José Manuel Jiménez
   413→ * @author Andres Morales
   414→ */
   415→function mostrarOcultarSucursales(elemento, empresa_id_padre) {
   416→    if ($(elemento).find('.bi-caret-down-fill').length > 0) {
   417→        $('.empresa-' + empresa_id_padre).removeClass('d-none');
   418→        $(elemento).find('.bi-caret-down-fill').removeClass('bi-caret-down-fill').addClass('bi-caret-up-fill');
   419→    } else {
   420→        $('.empresa-' + empresa_id_padre).addClass('d-none');
   421→        $(elemento).find('.bi-caret-up-fill').removeClass('bi-caret-up-fill').addClass('bi-caret-down-fill');
   422→    }
   423→}
   424→
   425→/**
   426→ * Mostrar/ocultar columnas opcionales.
   427→ * Usa el API de DataTables para controlar la visibilidad de las columnas.
   428→ *
   429→ * @returns {void}
   430→ * @author José Manuel Jiménez
   431→ * @author Andres Morales
   432→ */
   433→function mostrarOcultarColumnas() {
   434→    const MAPEO_COLUMNAS = { 'columna-ubicacion': 10, 'columna-numero-celular': 11, 'columna-correo-facturacion': 12, 'columna-fecha-creacion': 13, 'columna-progreso-creacion': 14, 'columna-tamano-empresa': 15, 'columna-sector': 16, 'columna-direccion': 17, 'columna-representante': 18 };
   435→
   436→    if (!tabla_empresas) return;
   437→
   438→    let cambios = [];
   439→    $('.filtro-columna').each(function() {
   440→        let valor = $(this).val();
   441→        let checked = $(this).prop('checked');
   442→        let indice_columna = MAPEO_COLUMNAS[valor];
   443→
   444→        if (indice_columna !== undefined) cambios.push({ indice: indice_columna, visible: checked });
   445→    });
   446→
   447→    cambios.forEach(cambio => { tabla_empresas.column(cambio.indice).visible(cambio.visible, false); });
   448→
   449→    tabla_empresas.columns.adjust().draw(false);
   450→    setTimeout(sincronizarEncabezadoTabla, 0);
   451→}
   452→
   453→/**
   454→ * Seleccionar/deseleccionar checkbox de empresa.
   455→ * Siguiendo el patrón de procesos/detalle.js
   456→ *
   457→ * @param {boolean} checked Estado del checkbox
   458→ * @param {number} empresa_id ID de la empresa
   459→ * @returns {void}
   460→ * @author José Manuel Jiménez
   461→ * @author Andres Morales
   462→ */
   463→function seleccionarCheckboxEmpresa(checked, empresa_id) {
   464→    empresa_id = parseInt(empresa_id);
   465→    if (checked) {
   466→        if (!empresas_seleccionadas.some(item => item.id == empresa_id)) {
   467→            let objeto = empresas_datos_ids.find(item => item.id == empresa_id);
   468→            if (objeto) {
   469→                empresas_seleccionadas.push(objeto);
   470→            }
   471→        }
   472→    } else {
   473→        empresas_seleccionadas = empresas_seleccionadas.filter(item => item.id != empresa_id);
   474→    }
   475→    validarSeleccionados();
   476→}
   477→
   478→/**
   479→ * Seleccionar todas las empresas visibles.
   480→ * Siguiendo el patrón de procesos/detalle.js
   481→ *
   482→ * @param {boolean} checked Estado del checkbox maestro
   483→ * @returns {void}
   484→ * @author José Manuel Jiménez
   485→ * @author Andres Morales
   486→ */
   487→function seleccionarTodasEmpresas(checked) {
   488→    empresas_seleccionadas = [];
   489→    if (checked) {
   490→        for (let i = 0; i < empresas_datos_ids.length; i++) {
   491→            if (empresas_datos_ids[i].tipo === 'empresa') {
   492→                empresas_seleccionadas.push(empresas_datos_ids[i]);
   493→            }
   494→        }
   495→    }
   496→    if ($(`#${nombre_tabla_empresas}`).hasClass('dataTable')) {
   497→        actualizarDatatables(nombre_tabla_empresas);
   498→    } else {
   499→        $('input.form-check-input[type="checkbox"]').prop('checked', checked);
   500→    }
   501→    validarSeleccionados();
   502→}
   503→
   504→/**
   505→ * Validar las empresas seleccionadas.
   506→ * Siguiendo el patrón de procesos/detalle.js
   507→ *
   508→ * @returns {void}
   509→ * @author José Manuel Jiménez
   510→ * @author Andres Morales
   511→ */
   512→function validarSeleccionados() {
   513→    if (empresas_seleccionadas.length == 0) {
   514→        $('#boton-descargar-excel-empresas').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar todo`);
   515→        $('#check-seleccionar-todos-empresas').prop('indeterminate', false);
