   554→function sincronizarEncabezadoTabla() {
   555→    if (!tabla_empresas) return;
   556→    tabla_empresas.columns(':visible').every(function() {
   557→        var nodos = $(this.nodes());
   558→        if (!nodos.length) return;
   559→        var ancho = nodos.eq(0).outerWidth();
   560→        if (!ancho) return;
   561→        $(this.header()).css({ width: ancho, minWidth: ancho });
   562→    });
   563→
   564→    // Ajustar el contenedor del encabezado para igualar el ancho del cuerpo
   565→    var contenedor = $(tabla_empresas.table().container());
   566→    var tabla_cuerpo = contenedor.find('.dataTables_scrollBody table');
   567→    var ancho_tabla = tabla_cuerpo.outerWidth();
   568→
   569→    if (ancho_tabla) {
   570→        var encabezado_scroll_interno = contenedor.find('.dataTables_scrollHeadInner');
   571→        encabezado_scroll_interno.width(ancho_tabla);
   572→        encabezado_scroll_interno.find('table').width(ancho_tabla);
   573→    }
   574→}
