   835→/**
   836→ * Formatear fecha y hora desde timestamp.
   837→ *
   838→ * @param {string} timestamp Timestamp en formato ISO.
   839→ * @returns {Object} Objeto con propiedades fecha y hora.
   840→ * @author Jair Carvajal
   841→ * @author Andres Morales
   842→ */
   843→function obtenerFechaHoraHistorial(timestamp) {
   844→    let fecha = new Date(timestamp);
   845→    let fecha_str = fecha.toISOString().split("T")[0];
   846→    let hora_str = fecha.toISOString().split("T")[1].split(".")[0];
   847→    return {fecha: fecha_str, hora: hora_str};
   848→}
