   866→function obtenerEstadoPlanCreditos(estado_id, nombre, por_facturar = 0, renovando = 0, empresa_plan_id = null, proximo = false, empresa_id, nombre_plan, creditos, creditos_plan = 0, creditos_disponibles = 0) {
   867→    let creditos_consumidos = creditos_plan - creditos_disponibles;
   868→    let detalle_empresa_plan = `onclick="abrirDetallePlanCreditos(${empresa_id}, '${nombre_plan}', ${creditos}, ${creditos_consumidos})"`;
   869→    if (empresa_plan_id != null) detalle_empresa_plan = `onclick="abrirDetallePlan(${empresa_plan_id})"`;
   870→
   871→    let estado_proximo = '';
