/**
 * Archivo principal del listado de empresas
 * @author Andres Morales
 */

var empresas_datos_ids = [];
var empresas_seleccionadas = [];
var nombre_tabla_empresas = 'tabla-empresas';
var json_filtros = {};
var filtro_html = '';
var paises = [];
var empresa_id_eliminar = null;
var tabla_empresas = null;
let creditos_empresa_id = null;
let creditos_totales_empresa = 0;
let creditos_consumidos_empresa = 0;

const CONFIGURACION_TABLAS = {
    autoWidth: true,
    responsive: false,
    processing: false,
    serverSide: false,
    searching: true,
    deferRender: true,
    paging: true,
    aaSorting: [],
    language: lenguaje_componente_datatables,
    lengthMenu: [[10, 25, 50, 100, 200], [10, 25, 50, 100, 200]],
    pageLength: 10,
    scrollY: 'calc(100vh - 500px)',
    scrollCollapse: true,
    scrollX: true,
};

tabla_empresas = $('#tabla-empresas').DataTable({
    ...CONFIGURACION_TABLAS,
    ajax: {
        url: '/empresas-listado-tabla',
        data: function(datos) {
            datos.solo_principales = true;
            datos.activo = archivadas ? false : true;
            datos.ordenar_sentido = $('#filtro_mas_recientes').val();
            datos.ordenar_por = 'created_at';

            if (json_filtros.estado_plan_filtro) datos.estado_plan_id = json_filtros.estado_plan_filtro;
            if (json_filtros.tipo_prueba_filtro) datos.tipo_prueba_id = json_filtros.tipo_prueba_filtro;
            if (json_filtros.plan_filtro) datos.plan_id = json_filtros.plan_filtro;
            if (json_filtros.ejecutivo_filtro) datos.ejecutivo_id = json_filtros.ejecutivo_filtro;
            if (json_filtros.pais_filtro) datos.pais_id = json_filtros.pais_filtro;
            if (json_filtros.departamento_filtro) datos.departamento_id = json_filtros.departamento_filtro;
            if (json_filtros.ciudad_filtro) datos.ciudad_id = json_filtros.ciudad_filtro;

            if (typeof json_filtros.fecha_creacion_filtro === 'string') {
                let partes_fecha = json_filtros.fecha_creacion_filtro.split(' a ');
                if (partes_fecha[0]) datos.fecha_creacion_desde = partes_fecha[0];
                if (partes_fecha[1]) datos.fecha_creacion_hasta = partes_fecha[1];
            }
        },
        dataSrc: function(json) {
            let filas = [];
            json.forEach(empresa => {
                filas.push({ ...empresa, tipo: 'empresa' });
                if (empresa.sucursales && empresa.sucursales.length > 0) {
                    empresa.sucursales.forEach(sucursal => {
                        filas.push({
                            ...sucursal,
                            tipo: 'sucursal',
                            empresa_id_padre: empresa.id,
                            plan_seleccion_padre: empresa.plan_procesos_de_seleccion,
                            plan_organizacional_padre: empresa.plan_procesos_organizacionales,
                            plan_vocacional_padre: empresa.plan_procesos_vocacionales
                        });
                    });
                }
            });
            return filas;
        }
    },
    columns: [
        {
            data: null,
            title: `<div class="check-container my-1 me-1">
                <input type="checkbox" id="check-seleccionar-todos-empresas" onchange="seleccionarTodasEmpresas(this.checked);"/>
            </div>`,
            orderable: false,
            className: 'text-center',
            render: (dato) => {
                let checked = empresas_seleccionadas.some(item => item.id == dato.id) ? 'checked' : '';
                return `<div class="check-container my-1 me-1">
                    <input type="checkbox" class="form-check-input" value="${dato.id}" onchange="seleccionarCheckboxEmpresa(this.checked, this.value);" ${checked}/>
                </div>`;
            }
        },
        {
            data: null,
            title: 'Suc.',
            orderable: false,
            className: 'text-start',
            render: (dato) => {
                if (dato.tipo === 'empresa' && dato.sucursales && dato.sucursales.length > 0) {
                    return `<div class="width-60px rounded-1 badge-estado-plan badge-estado-inactivo nowrap pointer" onclick="mostrarOcultarSucursales(this, ${dato.id})">
                        ${dato.sucursales_count} <i class="bi bi-caret-down-fill"></i>
                    </div>`;
                }
                return '';
            }
        },
        {
            data: null,
            title: 'ID',
            className: 'text-center',
            render: (dato) => dato.id || '-'
        },
        {
            data: null,
            title: 'Empresa',
            render: (dato) => dato.nombre_comercial || '-'
        },
        {
            data: null,
            title: 'Razon social',
            render: (dato) => dato.razon_social || '-'
        },
        {
            data: null,
            title: 'NIT',
            render: (dato) => dato.documento || '-'
        },
        {
            data: null,
            title: 'Ejecutivo',
            render: (dato) => dato.ejecutivo?.nombre_completo || '-'
        },
        {
            data: null,
            title: `
                <i class="bi bi-person-fill fs-5" onmouseover="mostrarTooltip(this)" onmouseout="ocultarTooltip(this)">
                    <span class="tooltip-bottom tooltip-icon-bottom">Selección</span>
                </i>
            `,
            className: 'px-3 text-center position-relative overflow-visible',
            render: (dato) => {
                let plan = dato.tipo === 'sucursal'
                    ? dato.plan_seleccion_padre
                    : dato.plan_procesos_de_seleccion;
                return obtenerEstadoPlan(
                    plan?.estado?.id,
                    plan?.estado?.nombre,
                    plan?.por_facturar,
                    plan?.renovando,
                    plan?.id,
                    plan?.plan_proximo
                );
            }
        },
        {
            data: null,
            title: `
                <img src="/iconos/icono_ia.svg" class="fs-5" onmouseover="mostrarTooltip(this)" onmouseout="ocultarTooltip(this)">
            `,
            className: 'px-3 text-center position-relative overflow-visible',
            render: (dato) => {
                let plan = dato?.plan_creditos || null;
                return obtenerEstadoPlanCreditos(
                    plan?.estado?.id,
                    plan?.estado?.nombre,
                    plan?.por_facturar,
                    plan?.renovando,
                    plan?.id,
                    plan?.plan_proximo,
                    plan?.empresa_id,
                    plan?.plan_credito?.nombre,
                    plan?.plan_credito?.creditos,
                    plan?.creditos_plan,
                    plan?.creditos_disponibles
                );
            }
        },
        {
            data: null,
            title: 'Ubicación',
            visible: false,
            render: (d) => d.ciudad?.nombre || '-'
        },
        {
            data: null,
            title: 'Número de celular',
            visible: false,
            render: (dato) => dato.celular || '-'
        },
        {
            data: null,
            title: 'Correo de facturación',
            visible: false,
            render: (dato) => dato.email_facturacion || '-'
        },
        {
            data: null,
            title: 'Fecha de creación',
            visible: false,
            render: (dato) => dato.created_at || '-'
        },
        {
            data: null,
            title: 'Progreso de creación',
            visible: false,
            render: (dato) => dato.porcentaje_creacion || '-'
        },
        {
            data: null,
            title: 'Tamaño de empresa',
            visible: false,
            render: (d) => d.tamano_empresa?.nombre || '-'
        },
        {
            data: null,
            title: 'Sector',
            visible: false,
            render: (d) => d.sector?.nombre || '-'
        },
        {
            data: null,
            title: 'Dirección',
            visible: false,
            render: (dato) => dato.direccion || '-'
        },
        {
            data: null,
            title: 'Representante legal',
            visible: false,
            render: (dato) => dato.nombre_representante || '-'
        },
        {
            data: null,
            title: 'Acciones',
            orderable: false,
            className: 'px-3 text-center',
            render: (dato) => {
                let texto_archivar = archivadas ? 'Desarchivar' : 'Archivar';
                return `
                    <div class="dropdown">
                        <i class="bi bi-three-dots dropdown-toggle text-blue-40 pointer" data-bs-toggle="dropdown" data-bs-auto-close="outside"></i>
                        <div class="dropdown-menu">
                            <a href="/empresas-gestionar/${dato.id}" class="dropdown-item no-visited pointer py-2">Gestionar empresa</a>
                            <div class="dropdown-item no-visited pointer py-2" onclick="abrirHistorialCambios(${dato.id}, '${dato.razon_social}', '${dato.creado_administrador}')">Historial de cambios</div>
                            <div class="dropdown-item no-visited pointer py-2" onclick="modalArchivarEmpresa(${dato.id})">${texto_archivar}</div>
                            <div class="dropdown-item no-visited pointer py-2" onclick="abrirDetalleArchivado(${dato.id}, '${dato.razon_social}', '${dato.comentario}')">Detalle de archivado</div>
                            <div class="dropdown-item no-visited pointer py-2" onclick="cambiarEmpresa(${dato.id},)">Cambiar a esta empresa</div>
                            <div class="dropdown-item no-visited pointer py-2 text-danger" onclick="modalEliminarEmpresa(${dato.id}, '${dato.razon_social}')">Eliminar</div>
                        </div>
                    </div>
                `;
            }
        }
    ],
    createdRow: function(row, dato) {
        if (dato.tipo === 'sucursal') {
            $(row).addClass(`empresa-${dato.empresa_id_padre} d-none bg-gray-90`);
            $(row).find('td').addClass('bg-gray-90');
        }
    },
    drawCallback: function() {
        empresas_datos_ids = $('#tabla-empresas').DataTable().data().toArray();

        // Aplicar estilos de fondo gris a las sucursales en todas las columnas visibles
        $('#tabla-empresas tbody tr').each(function() {
            if ($(this).hasClass('bg-gray-90')) {
                $(this).find('td').addClass('bg-gray-90');
            }
        });

        inicializarTooltips();
        sincronizarEncabezadoTabla();
        validarSeleccionados();
    },
    initComplete: function() {
        empresas_datos_ids = $('#tabla-empresas').DataTable().data().toArray();
        inicializarTooltips();
        cargarDataTablas();
        $('#tabla-empresas').parent().css('height', 'calc(100vh - 500px)');

        setTimeout(() => {
            if (tabla_empresas) {
                tabla_empresas.columns.adjust().draw(false);
                sincronizarEncabezadoTabla();
            }
        }, 100);
    }
});

$(document).ready(function() {
    $(document).on('change', '#filtro_mas_recientes', function() {
        actualizarDatatables(nombre_tabla_empresas);
    });

