/**
 * Cargar departamentos según país seleccionado.
 *
 * @param {number} pais_id ID del país
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function cargarDepartamentosFiltro(pais_id) {
    $('#departamento_filtro').empty().append('<option value="">Todos</option>');
    $('#ciudad_filtro').empty().append('<option value="">Todos</option>');

    if (!pais_id) return;

    const PAIS = paises.find(p => p.id == pais_id);
    if (PAIS?.departamentos) {
        PAIS.departamentos.forEach(dep => {
            $('#departamento_filtro').append(`<option value="${dep.id}">${dep.nombre}</option>`);
        });
    }
}

/**
 * Cargar ciudades según departamento seleccionado.
 *
 * @param {number} departamento_id ID del departamento
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function cargarCiudadesFiltro(departamento_id) {
    $('#ciudad_filtro').empty().append('<option value="">Todos</option>');

    if (!departamento_id) return;

    paises.forEach(pais => {
        const DEP = pais.departamentos?.find(d => d.id == departamento_id);
        if (DEP?.ciudades) {
            DEP.ciudades.forEach(ciudad => {
                $('#ciudad_filtro').append(`<option value="${ciudad.id}">${ciudad.nombre}</option>`);
            });
        }
    });
}

