/**
 * Mostrar/ocultar columnas opcionales.
 * Usa el API de DataTables para controlar la visibilidad de las columnas.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function mostrarOcultarColumnas() {
    const MAPEO_COLUMNAS = { 'columna-ubicacion': 10, 'columna-numero-celular': 11, 'columna-correo-facturacion': 12, 'columna-fecha-creacion': 13, 'columna-progreso-creacion': 14, 'columna-tamano-empresa': 15, 'columna-sector': 16, 'columna-direccion': 17, 'columna-representante': 18 };

    if (!tabla_empresas) return;

    let cambios = [];
    $('.filtro-columna').each(function() {
        let valor = $(this).val();
        let checked = $(this).prop('checked');
        let indice_columna = MAPEO_COLUMNAS[valor];

        if (indice_columna !== undefined) cambios.push({ indice: indice_columna, visible: checked });
    });

    cambios.forEach(cambio => { tabla_empresas.column(cambio.indice).visible(cambio.visible, false); });

    tabla_empresas.columns.adjust().draw(false);
    setTimeout(sincronizarEncabezadoTabla, 0);
}

/**
 * Seleccionar/deseleccionar checkbox de empresa.
 * Siguiendo el patrón de procesos/detalle.js
 *
 * @param {boolean} checked Estado del checkbox
 * @param {number} empresa_id ID de la empresa
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function seleccionarCheckboxEmpresa(checked, empresa_id) {
    empresa_id = parseInt(empresa_id);
    if (checked) {
        if (!empresas_seleccionadas.some(item => item.id == empresa_id)) {
            let objeto = empresas_datos_ids.find(item => item.id == empresa_id);
            if (objeto) {
                empresas_seleccionadas.push(objeto);
            }
        }
    } else {
        empresas_seleccionadas = empresas_seleccionadas.filter(item => item.id != empresa_id);
    }
    validarSeleccionados();
}

/**
 * Seleccionar todas las empresas visibles.
 * Siguiendo el patrón de procesos/detalle.js
 *
 * @param {boolean} checked Estado del checkbox maestro
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function seleccionarTodasEmpresas(checked) {
    empresas_seleccionadas = [];
    if (checked) {
        for (let i = 0; i < empresas_datos_ids.length; i++) {
            if (empresas_datos_ids[i].tipo === 'empresa') {
                empresas_seleccionadas.push(empresas_datos_ids[i]);
            }
        }
    }
    if ($(`#${nombre_tabla_empresas}`).hasClass('dataTable')) {
        actualizarDatatables(nombre_tabla_empresas);
    } else {
        $('input.form-check-input[type="checkbox"]').prop('checked', checked);
    }
    validarSeleccionados();
}

/**
 * Validar las empresas seleccionadas.
 * Siguiendo el patrón de procesos/detalle.js
 *
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function validarSeleccionados() {
    if (empresas_seleccionadas.length == 0) {
        $('#boton-descargar-excel-empresas').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar todo`);
        $('#check-seleccionar-todos-empresas').prop('indeterminate', false);
        $('#check-seleccionar-todos-empresas').prop('checked', false);
    } else if (empresas_seleccionadas.length == empresas_datos_ids.filter(d => d.tipo === 'empresa').length) {
        $('#boton-descargar-excel-empresas').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar seleccionados`);
        $('#check-seleccionar-todos-empresas').prop('indeterminate', false);
        $('#check-seleccionar-todos-empresas').prop('checked', true);
    } else {
        $('#boton-descargar-excel-empresas').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar seleccionados`);
        $('#check-seleccionar-todos-empresas').prop('indeterminate', true);
    }
}

