/**
 * Sincroniza los anchos entre el thead y el tbody cuando hay scroll horizontal.
 *
 * @returns {void}
 * @author Andres Morales
*/
function sincronizarEncabezadoTabla() {
    if (!tabla_empresas) return;
    tabla_empresas.columns(':visible').every(function() {
        var nodos = $(this.nodes());
        if (!nodos.length) return;
        var ancho = nodos.eq(0).outerWidth();
        if (!ancho) return;
        $(this.header()).css({ width: ancho, minWidth: ancho });
    });

    // Ajustar el contenedor del encabezado para igualar el ancho del cuerpo
    var contenedor = $(tabla_empresas.table().container());
    var tabla_cuerpo = contenedor.find('.dataTables_scrollBody table');
    var ancho_tabla = tabla_cuerpo.outerWidth();

    if (ancho_tabla) {
        var encabezado_scroll_interno = contenedor.find('.dataTables_scrollHeadInner');
        encabezado_scroll_interno.width(ancho_tabla);
        encabezado_scroll_interno.find('table').width(ancho_tabla);
    }
}

