    await $.ajax({
        type: 'POST',
        url : URL,
        data: {
            _token: $('meta[name="csrf-token"]').attr('content')
        }
    }).then((respuesta) => {
        enlace_creacion = respuesta.data;
        $('#enlace-creacion').text(enlace_creacion);
        $('#modal-generar-enlace').modal('show');
    }).catch((error) => {
        console.error(error);
    });
}

