/**
 * Formatear fecha y hora desde timestamp.
 *
 * @param {string} timestamp Timestamp en formato ISO.
 * @returns {Object} Objeto con propiedades fecha y hora.
 * @author Jair Carvajal
 * @author Andres Morales
 */
function obtenerFechaHoraHistorial(timestamp) {
    let fecha = new Date(timestamp);
    let fecha_str = fecha.toISOString().split("T")[0];
    let hora_str = fecha.toISOString().split("T")[1].split(".")[0];
    return {fecha: fecha_str, hora: hora_str};
}

/**
 * Obtener HTML de estado del plan con badges.
 *
 * @param {number} estado_id ID del estado
 * @param {string} nombre Nombre del estado
 * @param {number} por_facturar Si está por facturar
 * @param {number} renovando Si está renovando
 * @param {number} empresa_plan_id ID del plan empresa
 * @param {boolean} proximo Si tiene plan próximo
 * @param {number} empresa_id ID de la empresa
 * @param {string} nombre_plan Nombre del plan de créditos
 * @param {number} creditos Número de créditos del plan
 * @returns {string} HTML del estado
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function obtenerEstadoPlanCreditos(estado_id, nombre, por_facturar = 0, renovando = 0, empresa_plan_id = null, proximo = false, empresa_id, nombre_plan, creditos, creditos_plan = 0, creditos_disponibles = 0) {
    let creditos_consumidos = creditos_plan - creditos_disponibles;
    let detalle_empresa_plan = `onclick="abrirDetallePlanCreditos(${empresa_id}, '${nombre_plan}', ${creditos}, ${creditos_consumidos})"`;
    if (empresa_plan_id != null) detalle_empresa_plan = `onclick="abrirDetallePlan(${empresa_plan_id})"`;

    let estado_proximo = '';
    if (proximo) estado_proximo = `<span class="p-2 rounded-4 badge badge-proximo">Próximo: +1</span>`;

    let estado = '';
    if (por_facturar == 1) {
        estado = `<span class="p-2 rounded-4 badge-estado-por-facturar pointer" ${detalle_empresa_plan}>Por facturar${estado_proximo}</span>`;
    } else if (renovando == 1) {
        estado = `<span class="p-2 rounded-4 badge-estado-renovado pointer" ${detalle_empresa_plan}>Renovando${estado_proximo}</span>`;
    } else if (estado_id == 1) {
        estado = `<span class="p-2 rounded-4 badge-estado-activo pointer" ${detalle_empresa_plan}>${nombre}${estado_proximo}</span>`;
    } else if (estado_id == 2) {
        estado = `<span class="p-2 rounded-4 badge-estado-inactivo pointer" ${detalle_empresa_plan}>${nombre}${estado_proximo}</span>`;
    } else if (estado_id == 3) {
        estado = `<span class="p-2 rounded-4 badge-estado-proximo pointer" ${detalle_empresa_plan}>${nombre}${estado_proximo}</span>`;
    } else if (estado_id == 4) {
        estado = `<span class="p-2 rounded-4 badge-estado-por-vencer pointer" ${detalle_empresa_plan}>${nombre}${estado_proximo}</span>`;
    } else if (estado_id == 5) {
        estado = `<span class="p-2 rounded-4 badge-estado-vencido pointer" ${detalle_empresa_plan}>${nombre}${estado_proximo}</span>`;
    }

    return estado || '-';
}

