/**
 * Observar cambios en el contenedor de etiquetas para mostrar/ocultar el contenedor de consumo de créditos.
 *
 * @returns {void}
 * @author Daniel Beltrán
 */
function observarCambiosEtiquetasConsumoCreditos() {
    let $contenedor_etiquetas = $('#contenedor-chips-filtro_dropdown_consumo_creditos');
    let $envolvente           = $('#contenedor-chips-wrapper-filtro_dropdown_consumo_creditos');

    if ($contenedor_etiquetas.length === 0 || $envolvente.length === 0) return;

    let observador = new MutationObserver(function() {
        let tiene_etiquetas = $contenedor_etiquetas.children().length > 0;

        if (tiene_etiquetas) {
            $envolvente.removeClass('d-none');
        } else {
            $envolvente.addClass('d-none');
        }
    });

    observador.observe($contenedor_etiquetas[0], {
        childList: true,
        subtree: false
    });
}

/**
 * Aplicar los filtros avanzados.
 *
 * Esta función es llamada automáticamente por el componente crearFiltroDropdown.
 *
 * @param {string} campo_id ID del filtro.
 * @param {object} filtros Objeto con los filtros aplicados.
 * @returns {void}
 * @author Daniel Beltrán
 */
function aplicarFiltrosAvanzadosConsumoCreditos(campo_id) {
    if (campo_id === 'filtro_dropdown_consumo_creditos') {
        $('#tabla-consumo-creditos').DataTable().ajax.reload();
    }
}

window.__aplicarFiltrosDropdownHandlers = window.__aplicarFiltrosDropdownHandlers || [];
window.__aplicarFiltrosDropdownHandlers.push(aplicarFiltrosAvanzadosConsumoCreditos);

if (!window.aplicarFiltrosDropdown || !window.aplicarFiltrosDropdown.__esDispatcher) {
    window.aplicarFiltrosDropdown = function (filtro, filtros) {
        (window.__aplicarFiltrosDropdownHandlers || []).forEach(handler => handler(filtro, filtros));
    };
    window.aplicarFiltrosDropdown.__esDispatcher = true;
}

/**
 * Actualizar la barra de progreso de créditos consumidos/totales en el modal de consumo de créditos.
 *
 * @param {number|null} creditos_filtrados Créditos de las filas filtradas.
 * @returns {void}
 * @author Daniel Beltrán
 */
function actualizarBarraProgresoConsumoCreditos(creditos_filtrados = null) {
    let creditos_consumidos = creditos_consumidos_empresa || 0;
    let creditos_totales    = creditos_totales_empresa || 1;
    let creditos_mostrar    = creditos_filtrados !== null ? creditos_filtrados : creditos_consumidos;
    let porcentaje          = (creditos_mostrar / creditos_totales) * 100;

    const CONTENIDO = `
        <p class="text-label-2 mb-1">
            <img class="me-1" src="/iconos/icono_ia.svg" width="16" height="16" alt="Icono IA"> Créditos totales
        </p>
        ${crearProgressBar({
            label     : `${creditos_mostrar}/${creditos_totales}`,
            height    : '8px',
            porcentaje: { porcentaje, texto: false }
        })}
    `;

    $('#contenedor-progreso-creditos-consumo').empty().append(CONTENIDO);
}

/**
 * Descargar Excel del historial de créditos.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Esperanza Olivo
 */
function descargarExcelHistorialCreditos() {
    let ruta_descarga = `consumos-creditos-ia-exportar/${creditos_empresa_id}`;

    let parametros = { creditos_empresa_id };
    parametros.servicio_ia_id = $('#filtro_servicio_ia_id').val();
    parametros.usuario_id = $('#filtro_usuario_id').val();

    let desde = null;
    let hasta = null;
    let rango_fechas = $('#filtro_fecha_consumo').val();
    if (rango_fechas != '') {
        rango_fechas = rango_fechas.split(" a ");
        desde = rango_fechas[0];
        hasta = rango_fechas[1] || rango_fechas[0];

        parametros.rango_fechas;
        parametros.desde;
        parametros.hasta;
    }

    descargarExcel(ruta_descarga, 'consumos_creditos_ia', true, parametros)
}


/**
 * Abrir detalle de archivado de la empresa.
 *
 * @param {number} id ID de la empresa.
 * @param {string} razon_social Razón social.
 * @param {string} comentario Comentario de archivado.
 * @returns {void}
 * @author Daniel Beltrán
 * @author Esperanza Olivo
 */
async function abrirDetalleArchivado(id, razon_social, comentario) {
    $('#razon-social-archivado').text('');
    $('#responsable-archivado').text('');
    $('#fecha-archivado').text('');
    $('#comentario-archivado').text('');
    await $.ajax({
        type: 'GET',
        url : `/empresas-detalle-archivado/${id}`,
        success: function(respuesta) {
            const DETALLE = respuesta.data;
            if (DETALLE != null) {
                $('#razon-social-archivado').text(razon_social);
                $('#responsable-archivado').text(DETALLE.user.nombre_completo);
                $('#fecha-archivado').text(formatearFecha(DETALLE.created_at).fecha);
                $('#comentario-archivado').text(comentario);
            }
            $('#modal-detalle-archivado').modal('show');
        },
        error: function(error) {
            console.log(error);
        }
    });
}
